let trainingFilter={place:'all',goal:'all',gear:'all'},trainingSession=null,trainingTab='plans';
const trainingLabels={place:{all:'Усюди',home:'Вдома',gym:'У залі',outdoor:'Прогулянка / біг'},goal:{all:'Будь-яка ціль',start:'Почати',strength:'Сила й форма',muscle:'Набрати м’язи',cardio:'Витривалість'},gear:{all:'Будь-яке',none:'Без обладнання',band:'Резинка',dumbbell:'Гантелі',machine:'Тренажери'}};
function trainingFigure(pose){const points={squat:[[[48,27],[49,50],[43,70],[39,92],[65,69],[73,92]],[[48,27],[57,49],[68,66],[45,88],[79,67],[87,88]]],hinge:[[[50,27],[50,51],[45,71],[42,94],[66,70],[70,94]],[[64,33],[49,53],[45,72],[41,94],[67,71],[71,94]]],push:[[[48,29],[48,52],[43,72],[41,93],[67,72],[70,93]],[[61,31],[56,55],[45,73],[42,93],[70,72],[72,93]]],pull:[[[48,29],[48,51],[43,72],[40,93],[66,72],[70,93]],[[48,29],[48,51],[43,72],[40,93],[66,72],[70,93]]],lunge:[[[47,28],[48,51],[43,72],[40,94],[67,72],[72,94]],[[48,29],[52,52],[43,73],[34,92],[76,70],[83,92]]],bridge:[[[52,35],[50,60],[38,75],[29,87],[72,77],[82,87]],[[52,35],[57,57],[45,66],[28,87],[75,66],[82,87]]],core:[[[51,30],[50,54],[37,70],[25,81],[67,70],[79,81]],[[50,30],[50,55],[31,66],[20,73],[74,67],[87,73]]],step:[[[49,28],[49,52],[42,70],[40,91],[68,70],[70,91]],[[48,27],[49,50],[42,68],[42,88],[70,65],[79,77]]],walk:[[[49,28],[49,51],[40,72],[31,91],[67,72],[76,90]],[[49,28],[49,51],[42,72],[55,91],[65,72],[57,90]]]};let frames=points[pose]||points.walk;function body(p){const [head,hip,knee1,foot1,knee2,foot2]=p;return '<circle cx="'+head[0]+'" cy="'+head[1]+'" r="8"/><path d="M'+head[0]+' '+(head[1]+9)+' L'+hip.join(' ')+' M'+hip.join(' ')+' L'+knee1.join(' ')+' L'+foot1.join(' ')+' M'+hip.join(' ')+' L'+knee2.join(' ')+' L'+foot2.join(' ')+' M'+head[0]+' '+(head[1]+16)+' L'+(hip[0]-20)+' 58 M'+head[0]+' '+(head[1]+16)+' L'+(hip[0]+20)+' 58"/>';}return '<div class="training-figure" aria-label="Схематична 2D-ілюстрація двох фаз руху"><svg viewBox="0 0 220 110" aria-hidden="true"><path class="floor" d="M5 98 H215"/><g class="body first" transform="translate(0 0)">'+body(frames[0])+'</g><path class="move-arrow" d="M99 55 H120 m-7 -7 7 7 -7 7"/><g class="body second" transform="translate(115 0)">'+body(frames[1])+'</g></svg><span>СТАРТ <b>→</b> РУХ</span></div>';}
function trainingTimes(id){return Object.values(state.logs).flatMap(l=>l.workouts||[]).filter(w=>w.programId===id).length;}
function trainingStudio(){const list=TRAINING_PLANS.filter(p=>(trainingFilter.place==='all'||p.place===trainingFilter.place)&&(trainingFilter.goal==='all'||p.goal===trainingFilter.goal)&&(trainingFilter.gear==='all'||p.gear===trainingFilter.gear));return '<section class="training-studio" id="trainingStudio"><div class="training-title"><div><span>DAYMARK TRAINING / БІБЛІОТЕКА</span><h2>Тренування<br><em>під твій день.</em></h2><p>Дім, зал чи доріжка. Обери ціль і обладнання — побачиш зрозумілий план, техніку та свої записи.</p></div><div class="training-stamp">РУХ<br>ПО-<br>СВОЄМУ 🏋️</div></div><div class="training-filter-group"><span>ДЕ ТРЕНУЄШСЯ?</span><div>'+Object.entries(trainingLabels.place).map(([k,v])=>'<button data-action="training-filter" data-kind="place" data-id="'+k+'" class="'+(trainingFilter.place===k?'active':'')+'" aria-pressed="'+(trainingFilter.place===k)+'">'+v+'</button>').join('')+'</div></div><div class="training-filter-group"><span>ЩО ХОЧЕШ?</span><div>'+Object.entries(trainingLabels.goal).map(([k,v])=>'<button data-action="training-filter" data-kind="goal" data-id="'+k+'" class="'+(trainingFilter.goal===k?'active':'')+'" aria-pressed="'+(trainingFilter.goal===k)+'">'+v+'</button>').join('')+'</div></div><div class="training-filter-group"><span>ЩО Є ПІД РУКОЮ?</span><div>'+Object.entries(trainingLabels.gear).map(([k,v])=>'<button data-action="training-filter" data-kind="gear" data-id="'+k+'" class="'+(trainingFilter.gear===k?'active':'')+'" aria-pressed="'+(trainingFilter.gear===k)+'">'+v+'</button>').join('')+'</div></div><div class="training-list-heading"><b>'+list.length+' програм</b><small>15–45 хв · зміни фільтри під себе</small></div><div class="training-grid">'+(list.map((p,i)=>'<button class="training-card '+p.tone+'" data-action="training-open" data-id="'+p.id+'"><span class="training-index">'+String(i+1).padStart(2,'0')+' / '+trainingLabels.place[p.place]+'</span><span class="training-card-art" aria-hidden="true">'+({home:'⌂',gym:'🏋️',outdoor:'↗'}[p.place])+'</span><strong>'+p.name+'</strong><small>'+p.tag+' · '+p.items.length+' вправи</small><span class="training-card-foot"><b>'+p.minutes+' хв</b><i>Відкрити ↗</i></span></button>').join('')||'<div class="training-empty">Для такої комбінації ще немає програми. Зміни місце або обладнання.<button data-action="training-reset">Показати всі програми ↗</button></div>')+'</div><div class="training-principles"><b>Не «спали більше». А рухайся розумно.</b><p>Для силових — почни з контрольованих повторів і посильної ваги. Для ходьби й бігу — збільшуй обсяг поступово. Мета схуднення сама по собі не означає чотири підходи в кожній вправі.</p><details><summary>Як складені програми й коли зупинитися?</summary><p>Це стартові приклади для дорослих, не персональний тренер і не медичне призначення. 5 хв легкої розминки перед силовим блоком і кілька хвилин спокійного завершення. Відпочивай приблизно 60–120 с між підходами, довше за потреби. Обирай навантаження, де техніка зберігається; гострий біль, запаморочення чи незвичні симптоми — причина припинити вправу. Якщо є хвороба, вагітність, травма або післяопераційне відновлення, узгодь навантаження з фахівцем.</p><p>Загальні орієнтири: <a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">CDC: 150 хв руху й силові 2 дні/тиждень ↗</a> · <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM: регулярність, індивідуальність і прогрес ↗</a> · <a href="https://www.acefitness.org/resources/everyone/exercise-library/" target="_blank" rel="noopener">ACE: бібліотека техніки ↗</a>.</p></details></div></section>';}
function trainingOpen(id){const p=TRAINING_PLANS.find(x=>x.id===id);if(!p)return;const repeat=trainingTimes(id),other=TRAINING_PLANS.find(x=>x.place===p.place&&x.id!==p.id&&x.goal===p.goal);openModal('DAYMARK TRAINING / '+trainingLabels.place[p.place].toUpperCase(),'<div class="training-detail-head '+p.tone+'"><span>'+p.tag+' · '+p.minutes+' хв</span><h2>'+p.name+'</h2><p>'+p.items.length+' вправи · розминка 5 хв · спокійне завершення. Відпочивай між підходами за самопочуттям.</p></div>'+(repeat>=3?'<div class="training-repeat">Ти вже вніс / внесла цю програму '+repeat+' разів. Не обов’язково щоразу додавати вагу: спробуй кращий контроль руху або '+(other?'<button data-action="training-open" data-id="'+other.id+'">іншу програму ↗</button>':'додатковий день відновлення')+'.</div>':'')+'<p class="training-explain">Торкнись вправи, щоб побачити підказки. Схеми руху — 2D-ескізи, не 3D-інструкція; перевір техніку з тренером, якщо не впевнений / не впевнена.</p><div class="training-exercise-list">'+p.items.map(([id,sets],i)=>'<button data-action="training-exercise" data-id="'+id+'" data-plan="'+p.id+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+TRAINING_EXERCISES[id].name+'<small>'+TRAINING_EXERCISES[id].group+'</small></strong><b>'+sets+'</b><i>↗</i></button>').join('')+'</div><button class="btn blue full" data-action="training-start" data-id="'+p.id+'">Почати цю програму ↗</button><p class="training-fine">Повтори й підходи — стартовий орієнтир. Зменшуй обсяг, якщо потрібно. Біль — не показник ефективності.</p>');}
function trainingExercise(id,planId){const x=TRAINING_EXERCISES[id];if(!x)return;openModal('ТЕХНІКА / '+x.group.toUpperCase(),'<h2 class="modal-title">'+x.name+'</h2>'+trainingFigure(x.pose)+'<div class="training-cue"><span>01 / ЯК РУХАТИСЯ</span><p>'+x.cue+'</p></div><div class="training-cue caution"><span>02 / НА ЩО ЗВЕРНУТИ УВАГУ</span><p>'+x.check+'</p></div>'+(x.swap?'<button class="training-swap" data-action="training-exercise" data-id="'+x.swap+'" data-plan="'+(planId||'')+'">↗ Легший або інший варіант: '+TRAINING_EXERCISES[x.swap].name+'</button>':'')+'<p class="training-fine">Схема показує напрямок, але не замінює точну демонстрацію техніки. 3D-інструкції з перевіреними ракурсами — наступний етап.</p>'+(planId?'<button class="btn ghost full" data-action="'+(trainingSession?.id===planId?'training-return':'training-open')+'" data-id="'+planId+'">← '+(trainingSession?.id===planId?'До тренування':'До програми')+'</button>':''));}
function trainingStart(id){const p=TRAINING_PLANS.find(x=>x.id===id);if(!p)return;trainingSession={id,checked:new Set(),started:Date.now()};trainingSessionRender();}
function trainingSessionRender(){const p=TRAINING_PLANS.find(x=>x.id===trainingSession?.id);if(!p)return;openModal('ТРЕНУВАННЯ / '+p.name.toUpperCase(),'<div class="training-session-head"><span>ТИ В ПРОЦЕСІ 🏃</span><h2>'+p.name+'</h2><p>5 хв легкої розминки → вправи → спокійне завершення. Зроби паузу, коли потрібно.</p><b>'+trainingSession.checked.size+' / '+p.items.length+' позначено</b></div><div class="training-session-list">'+p.items.map(([id,sets],i)=>'<div class="training-session-item"><button data-action="training-check" data-id="'+id+'" aria-pressed="'+trainingSession.checked.has(id)+'" class="'+(trainingSession.checked.has(id)?'done':'')+'"><span>'+(trainingSession.checked.has(id)?'✓':'○')+'</span><strong>'+TRAINING_EXERCISES[id].name+'<small>'+sets+'</small></strong></button><button data-action="training-exercise" data-id="'+id+'" data-plan="'+p.id+'" aria-label="Техніка: '+TRAINING_EXERCISES[id].name+'">↗</button></div>').join('')+'</div><label class="form-label">Фактичний час, хв<input id="trainingActual" type="number" min="1" max="360" value="'+p.minutes+'"></label><button class="btn blue full" data-action="training-finish">Завершити й записати рух</button><p class="training-fine">Запишемо час і програму без вигаданих калорій. Пізніше можеш уточнити витрати в щоденнику.</p>');}
function trainingFinish(){const p=TRAINING_PLANS.find(x=>x.id===trainingSession?.id);if(!p)return;if(!trainingSession.checked.size){toast('Спершу познач виконану вправу');return;}const input=$('trainingActual');if(!input.reportValidity())return;const minutes=Number(input.value);if(!Number.isInteger(minutes)||minutes<1||minutes>360)return;const l=log();if(l.workouts.length>=100){toast('У цьому дні вже 100 активностей');return;}l.workouts.push({id:uid(),name:p.name,programId:p.id,minutes,activityId:null,source:'manual',activeKcal:null,grossKcal:null,weight:null,met:null,distance:null,startTime:'',notes:trainingSession.checked.size+' із '+p.items.length+' вправ позначено',countEnergy:false});l.habits.move=true;trainingSession=null;trainingTab='diary';persist();closeModal();navigate('move');toast('Тренування у твоєму щоденнику. Супер крок!');}
function trainingTabs(){return '<div class="training-tabs" role="group" aria-label="Розділ руху"><button data-action="training-tab" data-id="plans" class="'+(trainingTab==='plans'?'active':'')+'" aria-pressed="'+(trainingTab==='plans')+'">🏋️ Тренування</button><button data-action="training-tab" data-id="diary" class="'+(trainingTab==='diary'?'active':'')+'" aria-pressed="'+(trainingTab==='diary')+'">↗ Мій рух</button></div>';}
const baseSportView=sportView;
sportView=function(){return trainingTab==='plans'?pageTop('Обери рух для себе.','DAYMARK TRAINING / '+fdate(selectedDate),dateControl())+trainingTabs()+trainingStudio():baseSportView().replace('<section class="sport-hero">',trainingTabs()+'<section class="sport-hero">');};
sportHomeCard=function(){return '<button class="sport-home-card" data-action="training-home"><span class="sport-home-icon">'+dumbbellArt()+'</span><span><small>DAYMARK TRAINING · 14 ПРОГРАМ</small><strong>Тренування під твій день</strong><em>Дім, зал, ходьба й біг · обери своє</em></span><b>↗</b></button>';};
const baseNormalizeWorkout=normalizeWorkout;
normalizeWorkout=function(w,...args){const value=baseNormalizeWorkout(w,...args);value.programId=TRAINING_PLANS.some(p=>p.id===w.programId)?w.programId:null;return value;};
